class HaalCentraalAPIClient:
    attributes = Attributes

    def __init__(self, config: HaalCentraalConfig, submission: Submission):
        self.client = config.service.build_client()
        self.client.context = PreRequestClientContext(submission=submission)

    def retrieve_person(self, bsn: str, attributes: Iterable[str]) -> Dict[str, Any]:
        raise NotImplementedError

    def get_attribute(self, data: Dict[str, Any], attr: str) -> Any:
        return glom(data, attr)


class HaalCentraal13APIClient(HaalCentraalAPIClient):
    def retrieve_person(self, bsn: str, attributes: Iterable[str]) -> Dict[str, Any]:
        headers = dict(headers={"Accept": "application/hal+json"})
        return self.client.retrieve(
            "ingeschrevenpersonen",
            burgerservicenummer=bsn,
            url=f"ingeschrevenpersonen/{bsn}",
            request_kwargs=headers,
        )


class HaalCentraal20APIClient(HaalCentraalAPIClient):
    attributes = AttributesV2

    def retrieve_person(self, bsn: str, attributes: Iterable[str]) -> Dict[str, Any]:
        headers = dict(headers={"Content-Type": "application/json; charset=utf-8"})
        resource_body = {
            "type": "RaadpleegMetBurgerservicenummer",
            "burgerservicenummer": [bsn],
            "fields": attributes,
        }
        return self.client.operation(
            "Personen",
            data=resource_body,
            url="personen",
            request_kwargs=headers,
        )

    def get_attribute(self, data: Dict[str, Any], attr: str) -> Any:
        return glom(data["personen"][0], attr)


HAAL_CENTRAAL_CLIENTS: Dict[
    HaalCentraalVersion, Type[HaalCentraalAPIClient]
] = {
    HaalCentraalVersion.haalcentraal13: HaalCentraal13APIClient,
    HaalCentraalVersion.haalcentraal20: HaalCentraal20APIClient,
}


def get_haalcentraal_client(
    config: HaalCentraalConfig, submission: Submission
) -> HaalCentraalAPIClient:
    try:
        client_class = HAAL_CENTRAAL_CLIENTS[config.version]
    except KeyError as exc:
        raise InvalidPluginConfiguration(
            _("Unsupported Haal Centraal version: {version}").format(
                version=config.version
            )
        ) from exc

    return client_class(config, submission)


def get_correct_attributes():
    config = get_config()
    if not config:
        return Attributes

    try:
        return HAAL_CENTRAAL_CLIENTS[config.version].attributes
    except KeyError as exc:
        raise InvalidPluginConfiguration(
            _("Unsupported Haal Centraal version: {version}").format(
                version=config.version
            )
        ) from exc

api_client = get_haalcentraal_client(config, submission)

