def get_haalcentraal_client_class(config: HaalCentraalConfig) -> Type[HaalCentraalAPIClient]:
    try:
        return HAAL_CENTRAAL_CLIENTS[config.version]
    except KeyError as exc:
        raise InvalidPluginConfiguration(
            _("Unsupported Haal Centraal version: {version}").format(
                version=config.version
            )
        ) from exc


def get_haalcentraal_client(
    config: HaalCentraalConfig, submission: Optional[Submission]
) -> HaalCentraalAPIClient:
    return get_haalcentraal_client_class(config)(config, submission)


def get_correct_attributes():
    config = get_config()
    if not config:
        return Attributes

    return get_haalcentraal_client_class(config).attributes
